// Generated by npm run build. Edit lib/ instead.
// Pure parser: retain the original command and prompt wording, including :: weights.
function parseCommand(fullCommand = '') {
  const text = String(fullCommand);
  const starts = [];
  let quote = null;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '\\') { i++; continue; }
    if (quote) { if (c === quote) quote = null; continue; }
    // Apostrophes in words are not quoting delimiters.
    if ((c === '"' || c === "'") && (i === 0 || /\s/.test(text[i-1]))) { quote = c; continue; }
    if (c === '-' && text[i+1] === '-' && (i === 0 || /\s/.test(text[i-1]))) {
      const match = /^--([a-z][a-z0-9-]*)\b/i.exec(text.slice(i));
      if (match) { starts.push({start:i, end:i+match[0].length, name:match[1].toLowerCase()}); i += match[0].length-1; }
    }
  }
  const flags = {ar:null,v:null,stylize:null,chaos:null,weird:null,sref:[],profile:[],niji:null,raw:false,tile:false,iw:null};
  const aliases = {aspect:'ar',version:'v',s:'stylize',c:'chaos',w:'weird',p:'profile'};
  const unknown = {};
  let profile_default=false;
  const tokens = value => (value.match(/"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\S+/g) || []).map(s => /^(["']).*\1$/.test(s) ? s.slice(1,-1) : s);
  for (let i=0;i<starts.length;i++) {
    const part=starts[i], name=aliases[part.name] || part.name;
    const value=text.slice(part.end,starts[i+1]?.start ?? text.length).trim();
    if (name==='sref' || name==='profile') { flags[name].push(...tokens(value)); if(name==='profile'&&!value)profile_default=true; }
    else if (name==='raw' || name==='tile') flags[name]=true;
    else if (Object.hasOwn(flags,name)) flags[name]=value || true;
    else (unknown[name] ||= []).push(value || true);
  }
  return {prompt:text.slice(0,starts[0]?.start ?? text.length).trim(),full_command:text,flags,profile_default,unknown_flags:unknown};
}

// A run owns one scheduler. It must be explicitly started by the popup.
class ReadScheduler {
 constructor({sleep=ms=>new Promise(r=>setTimeout(r,ms)),now=()=>Date.now(),maxAttempts=3}={}) {this.sleep=sleep;this.now=now;this.maxAttempts=maxAttempts;this.last=-Infinity;this.stopped=false;this.tail=Promise.resolve();}
 stop(){this.stopped=true;}
 api(operation){const task=this.tail.then(()=>this.attempt(operation,true));this.tail=task.catch(()=>{});return task;}
 async attempt(operation,isAPI=false){
   for(let n=0;n<this.maxAttempts;n++){
     if(this.stopped)throw new Error('Run paused');
     if(isAPI){await this.sleep(Math.max(0,1000-(this.now()-this.last)));this.last=this.now();}
     if(this.stopped)throw new Error('Run paused');
     let result;
     try { result=await operation(); } catch (error) { this.stop(); throw error; }
     if(result.error){this.stop();throw new Error(result.error);}
     if(result.status>=200&&result.status<300)return result;
     if(result.challenge || result.status===401){this.stop();throw new Error(result.challenge?'Site challenge or warning: stopped':'Session expired: sign in on Midjourney');}
     const retry=[403,429].includes(result.status)||result.status>=500;
     if(!retry || n===this.maxAttempts-1){this.stop();throw new Error(`Read stopped after HTTP ${result.status}`);}
     await this.sleep(Math.max(2000*2**n,Math.min(120000,Number(result.retryAfterMs)||0)));
   }
 }
}
async function mapImages(items, operation, shouldStop=()=>false) {
 let next=0;const results=new Array(items.length);
 const settled=await Promise.allSettled(Array.from({length:Math.min(2,items.length)},async()=>{
  while(next<items.length&&!shouldStop()){const index=next++;results[index]=await operation(items[index],index);}
 }));
 const failure=settled.find(r=>r.status==='rejected');if(failure)throw failure.reason;
 return results;
}
function safeRelativePath(path) {
 if(typeof path!=='string'||!path||path.length>220||path.startsWith('/')||path.split('/').some(p=>!p||p==='.'||p==='..')||/[\\\x00-\x1f<>:"|?*]/.test(path))throw new Error('Invalid path');
 return path;
}

function normalizeJob(j) {
 const parsed=parseCommand(j.full_command||'');
 const type=`${j.job_type||''} ${j.event_type||''}`.toLowerCase();
 let kind='other';
 for(const [rx,k]of [[/zoom/,'zoom'],[/pan/,'pan'],[/remix/,'remix'],[/upscale|upsample/,'upscale'],[/variation|vary/,'variation']])if(rx.test(type)){kind=k;break;}
 if(kind==='other'&&!j.parent_id&&j.batch_size>1)kind='grid';
 const index=Number.isInteger(j.parent_index)?j.parent_index:Number.isInteger(j.parent_grid)?j.parent_grid:null;
 const count=Number.isInteger(j.batch_size)&&j.batch_size>0?Math.min(j.batch_size,4):1;
 return {job_id:j.id,created_at:j.enqueue_time||null,...parsed,parent_id:j.parent_id||null,parent_index:index,kind,image_files:[],image_urls:Array.from({length:count},(_,i)=>`https://cdn.midjourney.com/${j.id}/0_${i}.jpeg`),width:j.width??null,height:j.height??null,job_type:j.job_type??null,event_type:j.event_type??null,parent_grid:j.parent_grid??null,personalization_codes:j.personalization_codes||[],image_likes:j.image_likes||[],video:!!j.video_segments};
}
function normalizeBoards(boards,jobs){
 const references = new Map();
 for (const job of jobs) {
  for (const reference of job.personalization_codes || []) {
   if (!reference.id) continue;
   if (!references.has(reference.id)) references.set(reference.id, { codes: new Set(), jobs: new Set() });
   const entry = references.get(reference.id);
   if (reference.code) entry.codes.add(reference.code);
   entry.jobs.add(job.job_id);
  }
 }
 return boards.map(board => {
  const entry = references.get(board.moodboard_id);
  const codes = [...new Set([...(board.code ? [board.code] : []), ...(entry?.codes || [])])];
  return {
   id: board.moodboard_id, code: codes[0] || null, codes,
   name: board.title, version: board.version ?? null, created_at: board.created ?? null,
   generated_job_ids: [...(entry?.jobs || [])],
   images: (board.images || []).map(image => ({
    source_url: image.url, file: null, width: image.width ?? null, height: image.height ?? null,
   })),
  };
 });
}
function normalizeProfiles(data,identity,jobs){
 const codes=new Map();for(const j of jobs)for(const p of j.personalization_codes||[])if(p.id&&p.code){if(!codes.has(p.id))codes.set(p.id,new Set());codes.get(p.id).add(p.code);}
 const profiles=data.profiles.map(p=>({id:p.id,codes:[...new Set([...(codes.get(p.id)||[]),...(p.code?[p.code]:[])])],name:p.title,version:p.majorVersion,created_at:p.created,ratings_count:p.rankingCount,service:p.service,type:p.type}));
 for(const [key,version,service,label]of [['main','6','main','Global V6 Profile'],['mainV7','7','main','Global V7 Profile'],['niji','6','niji','Global Niji V6 Profile'],['nijiV7','7','niji','Global Niji V7 Profile']]){
  if(typeof data.counts?.[key]!=='number')continue;
  const id=`${identity.user_id}_${version}_${service}`;
  if(!profiles.some(p=>p.id===id))profiles.push({id,codes:[...(codes.get(id)||[])],name:label,version,ratings_count:data.counts[key],service,type:'global'});
 }
 return profiles;
}
function parentGaps(jobs){const ids=new Set(jobs.map(j=>j.job_id));return jobs.filter(j=>j.parent_id&&!ids.has(j.parent_id)).map(j=>({job_id:j.job_id,parent_id:j.parent_id,reason:'Parent is outside the selected subset or unavailable in the own feed'}));}
